When goroutines share mutable state, protect it with a sync.Mutex: import sync struct Counter {
mut: mu &sync.Mutex count int
} fn (mut c Counter) add(n int) { c.mu.lock() c.count += n c.mu.unlock()
} fn (c Counter) get() int { c.mu.lock() defer { c.mu.unlock() } return c.count
} fn main() { mut c := &Counter{ mu: sync.new_mutex() count: 0 } c.add(5) c.add(3) println(c.get())
} lock blocks until the mutex is available, then holds it for the scope of the block. Keep the critical section short. Use sync.RwMutex when reads are more frequent than writes. It allows multiple readers at once: import sync struct Cache {
mut: mu &sync.RwMutex data map[string]int
} fn (mut c Cache) set(key string, value int) { c.mu.lock() c.data[key] = value c.mu.unlock()
} fn (c Cache) get(key string) int { c.mu.rlock() defer { c.mu.runlock() } return c.data[key]
} fn main() { mut c := &Cache{ mu: sync.new_rwmutex() data: map[string]int{} } c.set('a', 1) c.set('b', 2) println(c.get('a')) println(c.get('b'))
} For a single value, use atomics from sync.stdatomic instead of a lock: import sync.stdatomic fn main() { mut counter := stdatomic.new_atomic(u64(0)) counter.add(1) counter.add(1) println(counter.load())
}

